package io.github.windyzhu3.ontologylaw.api;
import io.github.windyzhu3.ontologylaw.audit.AuditAppender;import io.github.windyzhu3.ontologylaw.execution.*;import io.github.windyzhu3.ontologylaw.identity.*;import io.github.windyzhu3.ontologylaw.identity.AuthorizationService.*;import io.github.windyzhu3.ontologylaw.lead.*;import io.github.windyzhu3.ontologylaw.opportunity.*;import io.github.windyzhu3.ontologylaw.party.*;
import java.sql.*;import java.util.*;
public final class R2CustomerRequirementsReadService {
 private final R2OpportunityLedgerReadService ledger;private final CurrentLeadReader leads;private final OpportunityCustomerRequirementsService versions;private final AuditAppender audit;private final OpportunityLedgerAuthorityReader authority=OpportunityLedgerAuthorityReader.databaseBacked();
 public R2CustomerRequirementsReadService(byte[] key,LeadProtection leads,OpportunityProgressProtection cipher,AuditAppender audit){ledger=new R2OpportunityLedgerReadService(key,leads,cipher,audit);this.leads=CurrentLeadReader.databaseBacked(leads);versions=R2CustomerRequirementsServices.create(cipher);this.audit=audit;}
 public Map<String,Object> read(Connection connection,Actor actor,UUID id,String query,boolean search)throws SQLException{if(query!=null&&query.length()>200)throw fail(400,"VALIDATION_FAILED");return CustomerRequirementsReadRuntime.read(connection,actor,audit,(c,now)->{var x=ledger.context(c,actor,id);if(x==null)throw fail(403,"NOT_AUTHORIZED");var disclosures=new ArrayList<AuditAppender.CustomerRequirementsDisclosureEntry>();for(var f:x.facts())disclose(c,actor,x,f,disclosures);var profiles=new ArrayList<Map<String,Object>>();for(var partyId:visiblePartyIds(c,actor,x.header().selector())){var meta=R1PartyReader.databaseBacked().active(c,actor.tenantId(),partyId);if(meta==null)continue;var exact=new Subject("party.party",meta.id(),meta.revision(),null);if(!authority.permitted(c,actor,x.organization(),List.of(exact),x.code()))continue;var p=CustomerPartyProfiles.databaseBacked().current(c,actor.tenantId(),partyId,false);if(p==null||!R2CustomerRequirementsServices.partySubject(p).equals(exact))throw fail(412,"STALE_SUBJECT");disclose(c,actor,x,R2CustomerRequirementsServices.partySubject(p),disclosures);if(query==null||p.name().toLowerCase(Locale.ROOT).contains(query.strip().toLowerCase(Locale.ROOT)))profiles.add(R2CustomerRequirementsServices.party(p));}
 Map<String,Object> result;if(search)result=Map.of("items",profiles.subList(0,Math.min(50,profiles.size())),"hasMore",profiles.size()>50);else{var out=new LinkedHashMap<String,Object>();out.put("opportunity",R2CustomerRequirementsServices.selector(x.header().selector()));out.put("responsibilityBasis",R2CustomerRequirementsServices.selector(x.owner().basis()));out.put("currentOwnerAppointmentId",x.owner().appointmentId().toString());out.put("closed",x.header().closed());var all=R2CustomerRequirementsServices.sourceFacts(c,actor.tenantId(),x.header().selector(),null);boolean editable=!x.header().closed()&&actor.appointmentId().equals(x.owner().appointmentId())&&authority.permitted(c,actor,x.organization(),all,"CUSTOMER_REQUIREMENTS_MANAGE");out.put("editable",editable);out.put("canCreateParty",editable);out.put("canMaintainSharedParty",editable&&authority.permitted(c,actor,x.organization(),all,"PARTY_PROFILE_MANAGE"));out.put("parties",profiles.subList(0,Math.min(50,profiles.size())));
 var source=new LinkedHashMap<String,Object>();source.put("lead",R2CustomerRequirementsServices.selector(x.lead()));var lead=leads.read(c,actor.tenantId(),x.lead().id());if(lead==null||!lead.selector().equals(x.lead()))throw fail(412,"STALE_SUBJECT");put(source,"name",lead.capturedName());put(source,"legalNeed",lead.legalNeedSummary());put(source,"contactName",lead.contactName());put(source,"contactPhone",lead.capturedPhone());if(lead.partyId()!=null){var p=CustomerPartyProfiles.databaseBacked().current(c,actor.tenantId(),lead.partyId(),false);if(p!=null&&authority.permitted(c,actor,x.organization(),List.of(R2CustomerRequirementsServices.partySubject(p)),x.code())){disclose(c,actor,x,R2CustomerRequirementsServices.partySubject(p),disclosures);source.put("party",R2CustomerRequirementsServices.party(p));}}out.put("source",source);
 var history=new ArrayList<Map<String,Object>>();var latestHistory=versions.history(c,actor.tenantId(),id);for(var m:latestHistory){var v=project(c,actor,x,m,disclosures);if(v!=null)history.add(v);}out.put("history",history.subList(0,Math.min(50,history.size())));if(!history.isEmpty()&&!latestHistory.isEmpty()&&history.getFirst().get("selector").equals(R2CustomerRequirementsServices.selector(latestHistory.getFirst().selector())))out.put("confirmation",history.getFirst());out.put("draftConsumed",false);if(!latestHistory.isEmpty()&&!out.containsKey("confirmation")){out.put("editable",false);out.put("canCreateParty",false);out.put("canMaintainSharedParty",false);}
 // Old responsibility drafts never follow a transferred Opportunity to its new owner.
 if(actor.appointmentId().equals(x.owner().appointmentId())){var d=versions.latestDraft(c,actor.tenantId(),id,x.owner().basis(),actor.appointmentId());if(d!=null){out.put("draftConsumed",out.containsKey("confirmation")&&!latestHistory.isEmpty()&&Objects.equals(latestHistory.getFirst().draft(),d.selector()));var v=project(c,actor,x,d,disclosures);if(v!=null)out.put("draft",v);}}result=out;}
 if(!x.equals(ledger.context(c,actor,id)))throw fail(412,"STALE_SUBJECT");for(var d:disclosures)if(!AuthorizationService.databaseBacked().evaluate(c,d.authorization().request(),true).allowed())throw fail(403,"NOT_AUTHORIZED");return new CustomerRequirementsReadRuntime.Prepared<>(result,List.copyOf(disclosures));});}
 private Map<String,Object> project(Connection c,Actor actor,R2OpportunityLedgerReadService.Context x,OpportunityCustomerRequirementsService.Metadata m,List<AuditAppender.CustomerRequirementsDisclosureEntry> ds)throws SQLException{var facts=R2CustomerRequirementsServices.sourceFacts(c,actor.tenantId(),x.header().selector(),m.selector());if(facts==null||!authority.permitted(c,actor,x.organization(),facts,x.code()))return null;for(var f:facts)disclose(c,actor,x,f,ds);var v=versions.read(c,actor.tenantId(),m.selector());if(v==null)throw fail(412,"STALE_SUBJECT");var partyFacts=v.partySnapshots().stream().map(OpportunityCustomerRequirementsService.Snapshot::selector).toList();if(!partyFacts.isEmpty()&&!authority.permitted(c,actor,x.organization(),partyFacts,x.code()))return null;for(var f:partyFacts)disclose(c,actor,x,f,ds);return Map.of("factRef",PublicFactReferences.reference(actor,m.selector().type(),m.selector().id()),"selector",R2CustomerRequirementsServices.selector(m.selector()),"document",v.document(),"partySnapshots",v.partySnapshots().stream().map(R2CustomerRequirementsServices::party).toList(),"actorAppointmentId",m.owner().toString(),"createdAt",m.createdAt().toString());}
 static Set<UUID> visiblePartyIds(Connection c,Actor actor,Subject current)throws SQLException{var out=new LinkedHashSet<UUID>();var opportunityIds=new LinkedHashSet<UUID>();opportunityIds.add(current.id());var reader=OpportunityLedgerReader.databaseBacked(new OpportunityProgressProtection(){public byte[] encrypt(UUID a,UUID b,UUID d,String s){throw new UnsupportedOperationException();}public String decrypt(UUID a,UUID b,UUID d,byte[] s){throw new UnsupportedOperationException();}});OpportunityLedgerReader.Position after=null;var observed=R1ServiceReadRuntime.databaseTime(c);while(true){var page=reader.scan(c,actor.tenantId(),observed,after,100);for(var row:page)opportunityIds.add(row.id());if(page.size()<100)break;after=page.getLast();}var authority=OpportunityLedgerAuthorityReader.databaseBacked();for(var id:opportunityIds){var opening=EventOpportunityReader.databaseBacked().byId(c,actor.tenantId(),id);if(opening==null)continue;var owner=OpportunityResponsibilityReader.databaseBacked().current(c,actor.tenantId(),opening.selector());var org=R2OpportunityOwnerExceptionAssembly.organization(c,actor.tenantId(),opening.selector());var facts=R2CustomerRequirementsServices.sourceFacts(c,actor.tenantId(),opening.selector(),null);if(facts==null||authority.code(c,actor,owner.appointmentId(),org,facts,R1ServiceReadRuntime.databaseTime(c))==null)continue;var lead=OpportunityLedgerLeadReader.metadataOnly(c,actor.tenantId(),opening.leadId());if(lead!=null&&lead.partyId()!=null)out.add(lead.partyId());var versions=R2CustomerRequirementsServices.create(new OpportunityProgressProtection(){public byte[] encrypt(UUID a,UUID b,UUID d,String s){throw new UnsupportedOperationException();}public String decrypt(UUID a,UUID b,UUID d,byte[] s){throw new UnsupportedOperationException();}});for(var m:versions.history(c,actor.tenantId(),id)){var refs=versions.participants(c,actor.tenantId(),m.selector());var all=new ArrayList<Subject>(refs);all.add(m.selector());String code=authority.code(c,actor,owner.appointmentId(),org,all,R1ServiceReadRuntime.databaseTime(c));if(code!=null)for(var ref:refs)if(ref.type().equals("party.party"))out.add(ref.id());}}UUID leadAfter=null;while(true){var page=CustomerPartyAnchors.databaseBacked().page(c,actor.tenantId(),leadAfter,100);for(var anchor:page){var org=authority.historicalOrganization(c,actor.tenantId(),anchor.owner());if(org==null)continue;var party=io.github.windyzhu3.ontologylaw.party.R1PartyReader.databaseBacked().active(c,actor.tenantId(),anchor.party());if(party==null)continue;var refs=List.of(anchor.lead(),anchor.assignment(),new Subject("party.party",party.id(),party.revision(),null));if(authority.code(c,actor,anchor.owner(),org,refs,R1ServiceReadRuntime.databaseTime(c))!=null)out.add(party.id());}if(page.size()<100)break;leadAfter=page.getLast().lead().id();}return Set.copyOf(out);}
 private void disclose(Connection c,Actor actor,R2OpportunityLedgerReadService.Context x,Subject f,List<AuditAppender.CustomerRequirementsDisclosureEntry> out)throws SQLException{var evidence=authority.evidence(c,actor,x.organization(),f,x.code());if(evidence==null||!evidence.allowed())throw fail(403,"NOT_AUTHORIZED");out.add(new AuditAppender.CustomerRequirementsDisclosureEntry(UUID.randomUUID(),UUID.randomUUID(),f,evidence));}
 private static void put(Map<String,Object> m,String k,Object v){if(v!=null)m.put(k,v);}
 private static R1ServiceReadRuntime.Failure fail(int status,String code){return new R1ServiceReadRuntime.Failure(status,code);}
}
